// The shape of checked-in seed files (seed/*.json) and the checks every seed must pass
// (PRD section 8, "Rules for seed data"). Seed files are generated by scripts in scripts/seed
// from fetched sources. They hold metadata and links only, never problem statements.
import { z } from 'zod';
import { TOPIC_IDS } from '../core/topics';
import { PLATFORMS } from '../core/types';
import { adapterFor } from '../platforms';

export const seedProblemSchema = z.object({
  platform: z.enum(PLATFORMS),
  platformId: z.string().min(1),
  displayId: z.string().min(1).nullable(),
  title: z.string().min(1),
  url: z.url(),
  difficultyRaw: z.string().min(1).nullable(),
  difficultyNorm: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4), z.literal(5)]).nullable(),
  topics: z.array(z.enum(TOPIC_IDS as [string, ...string[]])),
  sourceTags: z.array(z.string()),
});

export const starterSeedSchema = z.object({
  /** When the generating script ran. */
  generatedAt: z.iso.datetime(),
  /** Where the metadata was fetched from. */
  source: z.string().min(1),
  /** In starter-list order. */
  problems: z.array(seedProblemSchema).min(1),
});

export type SeedProblem = z.infer<typeof seedProblemSchema>;
export type StarterSeed = z.infer<typeof starterSeedSchema>;

/**
 * Checks that IDs and links are well-formed and unique. Returns one message per problem found;
 * an empty list means the seed is good.
 */
export function validateSeedProblems(problems: readonly SeedProblem[]): string[] {
  const errors: string[] = [];
  const seenIds = new Set<string>();
  const seenUrls = new Set<string>();

  problems.forEach((problem, index) => {
    const where = `#${index} ${problem.platform}:${problem.platformId}`;
    const key = `${problem.platform}:${problem.platformId}`;
    if (seenIds.has(key)) errors.push(`${where}: duplicate ID`);
    seenIds.add(key);
    if (seenUrls.has(problem.url)) errors.push(`${where}: duplicate URL ${problem.url}`);
    seenUrls.add(problem.url);

    if (problem.title.trim() !== problem.title) errors.push(`${where}: title has stray whitespace`);

    const adapter = adapterFor(problem.platform);
    if (!adapter) {
      errors.push(`${where}: no adapter for platform "${problem.platform}"`);
      return;
    }
    if (!adapter.isValidId(problem.platformId)) errors.push(`${where}: malformed ID`);
    const canonical = adapter.buildUrl(problem.platformId);
    if (problem.url !== canonical) errors.push(`${where}: URL ${problem.url} is not the canonical ${canonical}`);
    if (adapter.parseUrl(new URL(problem.url)) !== problem.platformId) {
      errors.push(`${where}: URL does not parse back to the ID`);
    }
    if (adapter.normalizeDifficulty(problem.difficultyRaw) !== problem.difficultyNorm) {
      errors.push(`${where}: normalized difficulty does not match "${problem.difficultyRaw}"`);
    }
  });
  return errors;
}
